export const ENCOUNTERS_BY_ID = new Map<string, EncounterDefinition>(
  MASTER_ENCOUNTERS.map((e) => [e.id, e])
);

export const SNACK_ENCOUNTERS = MASTER_ENCOUNTERS.filter((e) => e.category === "snack");
export const WINDOW_ENCOUNTERS = MASTER_ENCOUNTERS.filter((e) => e.requiresWindow || e.category === "spook" || e.category === "window");

export const RARITY_WEIGHTS: Record<EncounterRarity, number> = {
  common: 10.0,
  uncommon: 5.0,
  rare: 2.0,
  "very rare": 0.8,
  "ultra rare": 0.3,
  legendary: 0.1,
};

/**
 * Encounter Director: Enforces the 4 Core Encounter Rules
 */
export class EncounterDirector {
  private cooldowns: Map<string, number> = new Map();
  private lastEncounter: EncounterDefinition | null = null;
  private lastWasSpook: boolean = false;
  private consecutiveNegativeCount: number = 0;
  private turnCounter: number = 0;

  /**
   * Resets director state for a new climb
   */
  public reset() {
    this.cooldowns.clear();
    this.lastEncounter = null;
    this.lastWasSpook = false;
    this.consecutiveNegativeCount = 0;
    this.turnCounter = 0;
  }

  /**
   * Advances cooldown turns (ticks once per encounter spawn or floor ascent)
   */
  public tickTurn() {
    this.turnCounter++;
    for (const [id, remaining] of this.cooldowns.entries()) {
      if (remaining <= 1) {
        this.cooldowns.delete(id);
      } else {
        this.cooldowns.set(id, remaining - 1);
      }
    }
  }

  /**
   * Selects an encounter eligible for the current floor satisfying Rules 1-4.
   */
  public selectEncounter(options: {
    currentFloor: number;
    category?: EncounterCategory;
    requiresWindow?: boolean;
    onlyPositiveOrNeutral?: boolean;
    candidates?: EncounterDefinition[];
  }): EncounterDefinition | null {
    const { currentFloor, category, requiresWindow, onlyPositiveOrNeutral } = options;
    const pool = options.candidates || MASTER_ENCOUNTERS;

    const eligible = pool.filter((enc) => {
      // RULE 1: HEIGHT FILTER
      if (currentFloor < enc.minimumFloor || currentFloor > enc.maximumFloor) {
        return false;
      }

      // RULE 2: COOLDOWN CHECK
      const activeCooldown = this.cooldowns.get(enc.id) || 0;
      if (activeCooldown > 0) {
        return false;
      }

      // RULE 3: ANTI-SPAM RULE
      // If the previous event had "never_after_spook": true, the current event CANNOT be a spook
      if (this.lastWasSpook || (this.lastEncounter && this.lastEncounter.neverAfterSpook)) {
        if (enc.category === "spook" || enc.neverAfterSpook || enc.canCauseFall) {
          return false;
        }
      }

      // RULE 4: PACING - Do not flood player with negative events back-to-back
      if (this.consecutiveNegativeCount > 0 || onlyPositiveOrNeutral) {
        if (enc.valence === "negative" || enc.energyEffect < 0) {
          return false;
        }
      }

      // Category filter if specified
      if (category && enc.category !== category) {
        return false;
      }

      // Window requirement if specified
      if (requiresWindow !== undefined && enc.requiresWindow !== requiresWindow) {
        return false;
      }

      // RULE 5: SLIP-CAUSING SPOOKS & CAMERA FLASHES STRICTLY LEVEL 10+
      const isSlipOrFlash =
        enc.canCauseFall ||
        enc.movementEffect === 'drop_one_floor' ||
        enc.movementEffect === 'drop_half_floor' ||
        enc.visibilityEffect === 'camera_flash' ||
        enc.id.includes('flash') ||
        (enc.id.includes('camera') && enc.valence === 'negative');

      if (currentFloor < 10 && isSlipOrFlash) {
        return false;
      }

      return true;
    });

    if (eligible.length === 0) {
      // Fallback: pick any safe eligible common item within height range
      const fallback = pool.filter(
        (e) =>
          currentFloor >= e.minimumFloor &&
          currentFloor <= e.maximumFloor &&
          e.valence !== "negative" &&
          e.category !== "spook" &&
          !e.canCauseFall
      );
      if (fallback.length === 0) return null;
      return fallback[Math.floor(Math.random() * fallback.length)];
    }

    // Weighted random selection by rarity, with slip-causing spooks & camera flashes scaling up higher on building
    let totalWeight = 0;
    const weights = eligible.map((e) => {
      let w = RARITY_WEIGHTS[e.rarity] || 5.0;
      const isSlipOrFlash =
        e.canCauseFall ||
        e.movementEffect === 'drop_one_floor' ||
        e.movementEffect === 'drop_half_floor' ||
        e.visibilityEffect === 'camera_flash' ||
        e.id.includes('flash') ||
        (e.id.includes('camera') && e.valence === 'negative');

      if (currentFloor >= 10 && isSlipOrFlash) {
        // Increase more the higher the raccoon goes (Floor 10 to 25)
        const heightProgress = Math.min(1.0, Math.max(0, (currentFloor - 10) / 15));
        w *= 1.0 + heightProgress * 3.5;
      }

      totalWeight += w;
      return totalWeight;
    });

    const roll = Math.random() * totalWeight;
    let chosen: EncounterDefinition | null = eligible[0];
    for (let i = 0; i < eligible.length; i++) {
      if (roll <= weights[i]) {
        chosen = eligible[i];
        break;
      }
    }

    // STRICT HEIGHT ENFORCEMENT & DEBUG CHECK
    if (chosen) {
      if (currentFloor < chosen.minimumFloor || currentFloor > chosen.maximumFloor) {
        console.warn(`[DEBUG: Discarded event "${chosen.name}" - Floor ${currentFloor} outside range [${chosen.minimumFloor}, ${chosen.maximumFloor}]]`);
        return null;
      }
      console.log(`[DEBUG: Floor: ${currentFloor} | Category: ${chosen.category} | Event: "${chosen.name}" | Min-Max Check: PASSED]`);
    }

    return chosen;
  }

  /**
   * Registers that an encounter was triggered, recording cooldown and updating pacing history.
   */
  public recordTrigger(encounter: EncounterDefinition) {
    this.tickTurn();
    this.cooldowns.set(encounter.id, encounter.cooldown);
    this.lastEncounter = encounter;
    this.lastWasSpook = encounter.category === "spook" || encounter.neverAfterSpook || encounter.canCauseFall;
    if (encounter.valence === "negative" || encounter.energyEffect < 0) {
      this.consecutiveNegativeCount++;
    } else {
      this.consecutiveNegativeCount = 0;
    }
  }

  /**
   * Checks if an encounter ID is currently on cooldown
   */
  public isCoolingDown(id: string): boolean {
    return (this.cooldowns.get(id) || 0) > 0;
  }

  /**
   * Gets remaining cooldown turns for an encounter ID
   */
  public getRemainingCooldown(id: string): number {
    return this.cooldowns.get(id) || 0;
  }

  public getLastEncounter(): EncounterDefinition | null {
    return this.lastEncounter;
  }
}
